;---------------------------------------------------------------------------
; CODE_polar_proj_check -- 2D polar-to-cartesian vector projection + check.
; Reads sin[R9] and cos[R9] from Bank08's DATA_m_sin/DATA_m_cos tables (via cross-bank
; ROMB), then FMULTs them against R4 (length) to get the rotated (x, y) delta
; in R5/R10. Subtracts a check value (R7) and compares against a bound; sets
; SMS($3E) = 1 (hit) or 0 (miss), storing the projected y at SMS($3C) on hit.
; Used by Mode-7-driven boss aim / line-of-sight checks.
;---------------------------------------------------------------------------

CODE_0B8500:
CODE_polar_proj_check:                   ; polar (angle R9, len R4) -> XY proj + bound test
	IBT R0, #DATA_08AB98>>16
	ROMB
	IWT R0, #DATA_08AC18
	TO R14
	ADD R9
	IWT R0, #DATA_08AB98
	TO R10
	ADD R9
	GETB
	INC R14
	GETBH
	MOVE R11, R0
	MOVE R6, R4
	TO R5
	FMULT
	MOVE R14, R10
	GETB
	INC R14
	GETBH
	MOVE R10, R0
	MOVE R6, R1
	FMULT
	SUB R5
	SUB R7
	XOR R12
	BPL CODE_0B8556 : SUB R0
	MOVE R6, R4
	FROM R11
	FMULT
	ADD R7
	LOB
	TO R6
	SWAP
	FROM R2
	TO R3
	FMULT
	IBT R5, #$08
	MOVE R6, R4
	FROM R10
	FMULT
	SUB R3
	MOVE R7, R0
	MOVES R13, R13
	BNE CODE_0B854C : NOP
	SUB R8
	ADD R5
	WITH R5
	ADD R5
	CMP R5
	BCS CODE_0B8556 : SUB R0
CODE_0B854C:
	SMS ($3C), R7
	IBT R0, #$01
	SMS ($3E), R0
	STOP : NOP

CODE_0B8556:
	SMS ($3E), R0
	STOP : NOP

;---------------------------------------------------------------------------
; CODE_polar_to_xy_simple -- short polar-to-cartesian conversion.
; Same trig-table read pattern as CODE_polar_proj_check but with no bound test --
; just R1 := R2 * sin(R1) and R0 := R2 * cos(R1). Used by simpler effect
; spawners that need a directional velocity from an angle/length pair.
;---------------------------------------------------------------------------

CODE_0B855B:
CODE_polar_to_xy_simple:                 ; (angle R1, len R2) -> R1=R2*sin, R0=R2*cos
	IBT R0, #DATA_08AB98>>16
	ROMB
	IWT R0, #DATA_08AC18
	TO R14
	ADD R1
	IWT R0, #DATA_08AB98
	TO R10
	ADD R1
	GETB
	INC R14
	GETBH
	TO R1
	FMULT
	MOVE R14, R10
	GETB
	INC R14
	GETBH
	FMULT
	STOP : NOP

CODE_0B8578:
	FMULT
	ADD R7
	SMS ($3C), R0
	ADD R0
	INC R0
	SMS ($38), R0
	MOVE R6, R9
	FROM R1
	FMULT
	SMS ($36), R0
	ADD R8
	ADD R3
	SMS ($3E), R0
	ADD R0
	INC R0
	SMS ($3A), R0
	STOP : NOP

CODE_0B8595:
	LINK #4
	IWT R15, #CODE_0B859C : NOP
	STOP : NOP

CODE_0B859C:
CODE_sincos_mult_rounded:                ; (R1 angle, R4 scalar) -> R1=R4*sin, R4=R4*cos (rounded mid)
	IBT R0, #DATA_08AB98>>16
	ROMB
	IWT R0, #DATA_08AC18
	TO R14
	ADD R1
	IWT R0, #DATA_08AB98
	TO R2
	ADD R1
	GETB
	INC R14
	GETBH
	LMULT
	IWT R3, #$0080
	WITH R4
	ADD R3
	ADC #0
	WITH R4
	HIB
	LOB
	SWAP
	TO R1
	OR R4
	MOVE R14, R2
	GETB
	INC R14
	GETBH
	LMULT
	WITH R4
	ADD R3
	ADC #0
	WITH R4
	HIB
	LOB
	SWAP
	OR R4
	JMP R11 : NOP

CODE_0B85D0:
CODE_sincos_proj_to_xy:                  ; (R1 angle) -> R8=sin*hi, R7=cos*hi; multiply against scratch ref
	IBT R0, #DATA_08AB98>>16
	ROMB
	IWT R0, #DATA_08AC18
	TO R14
	ADD R1
	IWT R0, #DATA_08AB98
	TO R2
	ADD R1
	GETB
	INC R14
	GETBH
	LMULT
	WITH R4
	HIB
	LOB
	SWAP
	TO R8
